ALTER TABLE "events" ADD CONSTRAINT "events_requirements_keys" CHECK (("events"."requirements" - array['identity','email','liveness','age_min']) = '{}'::jsonb and ("events"."max_age" - array['identity','face','age']) = '{}'::jsonb);--> statement-breakpoint
ALTER TABLE "events" ADD CONSTRAINT "events_requirements_types" CHECK ((not ("events"."requirements" ? 'identity') or jsonb_typeof("events"."requirements"->'identity') = 'boolean') and (not ("events"."requirements" ? 'email') or jsonb_typeof("events"."requirements"->'email') = 'boolean') and (not ("events"."requirements" ? 'liveness') or jsonb_typeof("events"."requirements"->'liveness') = 'boolean') and (not ("events"."requirements" ? 'age_min') or (jsonb_typeof("events"."requirements"->'age_min') = 'number' and ("events"."requirements"->>'age_min')::numeric between 1 and 100 and mod(("events"."requirements"->>'age_min')::numeric,1)=0)));--> statement-breakpoint
ALTER TABLE "events" ADD CONSTRAINT "events_age_consistent" CHECK ("events"."age_min" is null or not ("events"."requirements" ? 'age_min') or "events"."age_min" = ("events"."requirements"->>'age_min')::numeric);--> statement-breakpoint
ALTER TABLE "events" ADD CONSTRAINT "events_max_age_identity" CHECK (not ("events"."max_age" ? 'identity') or (jsonb_typeof("events"."max_age"->'identity') = 'number' and ("events"."max_age"->>'identity')::numeric > 0 and ("events"."max_age"->>'identity')::numeric <= 31536000 and mod(("events"."max_age"->>'identity')::numeric,1)=0));--> statement-breakpoint
ALTER TABLE "events" ADD CONSTRAINT "events_max_age_face" CHECK (not ("events"."max_age" ? 'face') or (jsonb_typeof("events"."max_age"->'face') = 'number' and ("events"."max_age"->>'face')::numeric > 0 and ("events"."max_age"->>'face')::numeric <= 15552000 and mod(("events"."max_age"->>'face')::numeric,1)=0));--> statement-breakpoint
ALTER TABLE "events" ADD CONSTRAINT "events_max_age_age" CHECK (not ("events"."max_age" ? 'age') or (jsonb_typeof("events"."max_age"->'age') = 'number' and ("events"."max_age"->>'age')::numeric > 0 and ("events"."max_age"->>'age')::numeric <= 31536000 and mod(("events"."max_age"->>'age')::numeric,1)=0));